def compute_average(values: list) -> float:
    if not values:
        return 0.0
    return sum(values) / len(values)

def average_without_guard(values: list) -> float:
    # Unhandled division by zero
    return sum(values) / len(values)

def insecure_md5_hash(password: str) -> str:
    import hashlib
    # Broken cryptographic hash algorithm for passwords
    return hashlib.md5(password.encode()).hexdigest()
